 "Functions": [
  {
   "ID": 1,
   "Function": "loadDatabase()",
   "File": "js/main.js",
   "Trigger": "Page load",
   "Description": "Reads database/Dea_Database.xlsx with SheetJS. If it cannot (for example when index.html is opened as a file), it uses js/data.js, a copy generated from the same Excel."
  },
  {
   "ID": 2,
   "Function": "applyUI()",
   "File": "js/main.js",
   "Trigger": "After data loads",
   "Description": "Replaces the text of every element with a data-ui attribute by the Label of the matching Key in the UI_Elements sheet."
  },
  {
   "ID": 3,
   "Function": "renderSection(section)",
   "File": "js/main.js",
   "Trigger": "After data loads",
   "Description": "Builds the cards of each section from the Content sheet, filtered by the Section column."
  },
  {
   "ID": 4,
   "Function": "initReveal()",
   "File": "js/main.js",
   "Trigger": "Scroll",
   "Description": "Fades and slides elements into view when they enter the screen (IntersectionObserver)."
  },
  {
   "ID": 5,
   "Function": "animateCounters()",
   "File": "js/main.js",
   "Trigger": "Scroll",
   "Description": "Counts the key statistics up from zero the first time they are visible."
  },
  {
   "ID": 6,
   "Function": "toggleMenu()",
   "File": "js/main.js",
   "Trigger": "Click on Menu",
   "Description": "Opens and closes the navigation on small screens."
  },
  {
   "ID": 7,
   "Function": "initScene()",
   "File": "js/three-scene.js",
   "Trigger": "Page load",
   "Description": "Draws the floating 3D objects (cap, book, scale, shapes) of the hero with Three.js and reacts to the mouse."
  },
  {
   "ID": 8,
   "Function": "initCharts()",
   "File": "js/charts.js",
   "Trigger": "Page load",
   "Description": "Builds the interactive charts from the Chart_Data sheet with Chart.js."
  },
  {
   "ID": 9,
   "Function": "setScenario(name)",
   "File": "js/charts.js",
   "Trigger": "Click on chart filter",
   "Description": "Shows the selected 2050 scenario in the schooling chart."
  },
  {
   "ID": 10,
   "Function": "updateYear(value)",
   "File": "js/charts.js",
   "Trigger": "Move year slider",
   "Description": "Shows the value of every scenario for the selected year."
  },
  {
   "ID": 11,
   "Function": "startStory(name)",
   "File": "js/whatif.js",
   "Trigger": "Click on a story tab",
   "Description": "Starts a What If? story from the What_If sheet and resets the Education and Equality meters."
  },
  {
   "ID": 12,
   "Function": "choose(option)",
   "File": "js/whatif.js",
   "Trigger": "Click on a choice",
   "Description": "Shows the result of the choice and moves the Education and Equality meters."
  },
  {
   "ID": 13,
   "Function": "nextStep()",
   "File": "js/whatif.js",
   "Trigger": "Click on Next decision",
   "Description": "Shows the next decision of the story."
  },
  {
   "ID": 14,
   "Function": "showEnding()",
   "File": "js/whatif.js",
   "Trigger": "Click on See 2050",
   "Description": "Shows the 2050 ending (High / Medium / Low) that matches the total points."
  },
  {
   "ID": 15,
   "Function": "filterActions(place)",
   "File": "js/main.js",
   "Trigger": "Click on Home / School / Community / Social media",
   "Description": "Shows only the actions for that place (Tag column)."
  },
  {
   "ID": 16,
   "Function": "updatePledgeChart()",
   "File": "js/charts.js",
   "Trigger": "Pledge toggled",
   "Description": "Updates the doughnut chart with your pledges, by place."
  },
  {
   "ID": 17,
   "Function": "togglePledge(id)",
   "File": "js/main.js",
   "Trigger": "Click on I'll do it",
   "Description": "Saves or removes a pledge in localStorage and updates the progress ring."
  },
  {
   "ID": 18,
   "Function": "resetPledges()",
   "File": "js/main.js",
   "Trigger": "Click on Reset pledges",
   "Description": "Deletes all pledges stored in this browser."
  },
  {
   "ID": 19,
   "Function": "sharePage()",
   "File": "js/main.js",
   "Trigger": "Click on Share this page",
   "Description": "Opens the native share menu or copies the link to the clipboard."
  },
  {
   "ID": 20,
   "Function": "startGame()",
   "File": "js/game.js",
   "Trigger": "Click on Start game",
   "Description": "Starts the Catch the knowledge mini game with the items in the Game sheet."
  },
  {
   "ID": 21,
   "Function": "togglePause()",
   "File": "js/game.js",
   "Trigger": "Click on Pause or press P",
   "Description": "Pauses or resumes the game."
  },
  {
   "ID": 22,
   "Function": "renderReferences()",
   "File": "js/main.js",
   "Trigger": "After data loads",
   "Description": "Prints the APA references of the References sheet in the Legal section, with italics and clickable links."
  },
  {
   "ID": 23,
   "Function": "copyReferences()",
   "File": "js/main.js",
   "Trigger": "Click on Copy references",
   "Description": "Copies the full APA reference list to the clipboard."
  },
  {
   "ID": 24,
   "Function": "playVideo()",
   "File": "js/main.js",
   "Trigger": "Click on Play",
   "Description": "Plays the presentation video in the Meet Us section."
  }
 ],
