 "Guide": [
  {
   "Column / Topic": "ID",
   "Description": "Unique, consecutive number of the row."
  },
  {
   "Column / Topic": "Section",
   "Description": "Defines in which part of the web page the block will go. Fixed labels: SDG, Projections 2050, Take Action, Legal, Meet Us. The page uses them to build each section."
  },
  {
   "Column / Topic": "Topic",
   "Description": "The specific title or header of that card or paragraph (for example: SDG 5 · Gender Equality, or Trend scenario)."
  },
  {
   "Column / Topic": "Information",
   "Description": "100% of the text written by the team: the complete paragraph, ready to be published. The page prints the contents of this cell literally."
  },
  {
   "Column / Topic": "Source",
   "Description": "Official name of the institution, report or author the data comes from."
  },
  {
   "Column / Topic": "Link",
   "Description": "The direct link to the page consulted, to avoid plagiarism and to show a 'See source' button on the web. Leave empty to hide the button."
  },
  {
   "Column / Topic": "Tag",
   "Description": "Optional hint for the page. In Take Action it is the place where you act: Home, School, Community or Social media (it creates the filter buttons)."
  },
  {
   "Column / Topic": "Sheets",
   "Description": "Content = texts · What_If = interactive stories · UI_Elements = every button, label and control · Functions = what each function does · Chart_Data = numbers of the charts · Game = mini game items · Palette = colours · References = APA sources · Settings = general texts and file paths."
  },
  {
   "Column / Topic": "What_If",
   "Description": "One row per option (A or B) of each decision. Education and Equality are the points each choice adds or removes. Rows with Step = Ending hold the three 2050 endings (High, Medium, Low). Intro only in the first row of each story."
  },
  {
   "Column / Topic": "References",
   "Description": "Every source in APA 7th edition. The APA column is printed on the page; *asterisks* mark the part shown in italics."
  },
  {
   "Column / Topic": "Updating",
   "Description": "Edit this file and upload it to GitHub: the published page reads it directly. To also update the offline copy (js/data.js) run: python3 tools/excel_to_js.py"
  }
 ]
